from unittest.mock import patch

import pytest


def _raw_tip(
    address: str = "alice@example.com",
    auto_reply_html: str | None = None,
    mailbox_full: bool = False,
    max_message_size: int | None = 36700160,
    recipient_scope: str | None = "organization",
    delivery_restricted: bool = False,
) -> dict:
    tip: dict = {
        "emailAddress": {"name": "Alice", "address": address},
        "automaticReplies": {},
        "mailboxFull": mailbox_full,
        "maxMessageSize": max_message_size,
        "recipientScope": recipient_scope,
        "deliveryRestriction": {"isDeliveryRestricted": delivery_restricted},
    }
    if auto_reply_html is not None:
        tip["automaticReplies"]["message"] = auto_reply_html
    return tip


