@patch("src.microsoft_mcp.tools.graph")
def test_get_mailtips_flattens_tip_shape(mock_graph):
    from src.microsoft_mcp import tools

    mock_graph.request.return_value = {
        "value": [
            _raw_tip(
                address="alice@example.com",
                auto_reply_html=None,
                mailbox_full=False,
                max_message_size=36700160,
                recipient_scope="organization",
                delivery_restricted=False,
            )
        ]
    }

    result = tools.get_mailtips.fn(emails=["alice@example.com"])

    assert len(result) == 1
    tip = result[0]
    assert tip["email"] == "alice@example.com"
    assert tip["auto_reply"] is None
    assert tip["mailbox_full"] is False
    assert tip["max_message_size_bytes"] == 36700160
    assert tip["recipient_scope"] == "organization"
    assert tip["delivery_restricted"] is False


@patch("src.microsoft_mcp.tools.graph")
def test_get_mailtips_strips_html_from_auto_reply(mock_graph):
    from src.microsoft_mcp import tools

    html_reply = "<p>I am <b>out of office</b> until Monday.</p>"
    mock_graph.request.return_value = {
        "value": [_raw_tip(address="bob@example.com", auto_reply_html=html_reply)]
    }

    result = tools.get_mailtips.fn(emails=["bob@example.com"])

    tip = result[0]
    assert "<" not in tip["auto_reply"]
    assert "out of office" in tip["auto_reply"]
    assert "Monday" in tip["auto_reply"]


